    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof createReorderRule>>, TError,CreateReorderRuleMutationVariables, TContext>, request?: SecondParameter<typeof customFetch>}
): UseMutationOptions<Awaited<ReturnType<typeof createReorderRule>>, TError,CreateReorderRuleMutationVariables, TContext> => {

const mutationKey = getCreateReorderRuleMutationKey();
const {mutation: mutationOptions, request: requestOptions} = options ?
      options.mutation && 'mutationKey' in options.mutation && options.mutation.mutationKey ?
      options
      : {...options, mutation: {...options.mutation, mutationKey}}
      : {mutation: { mutationKey, }, request: undefined};




      const mutationFn: MutationFunction<Awaited<ReturnType<typeof createReorderRule>>, CreateReorderRuleMutationVariables> = (props) => {
          const {data} = props ?? {};

          return  createReorderRule(data,requestOptions)
        }






  return  { mutationFn, ...mutationOptions }}

    export type CreateReorderRuleMutationResult = NonNullable<Awaited<ReturnType<typeof createReorderRule>>>
    export type CreateReorderRuleMutationBody = BodyType<ReorderRuleInput>
    export type CreateReorderRuleMutationError = ErrorType<unknown>
    export type CreateReorderRuleMutationVariables = {data: BodyType<ReorderRuleInput>}

    /**
 * @summary Create replenishment rule
 */
export const useCreateReorderRule = <TError = ErrorType<unknown>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof createReorderRule>>, TError,CreateReorderRuleMutationVariables, TContext>, request?: SecondParameter<typeof customFetch>}
 ): UseMutationResult<
        Awaited<ReturnType<typeof createReorderRule>>,
        TError,
        CreateReorderRuleMutationVariables,
        TContext
      > => {
      return useMutation(getCreateReorderRuleMutationOptions(options));
    }

